Built this against the Aura UI/UX platform rules (44pt iOS / 48dp Android touch targets, iOS alert vs. Android two-action dialog for the destructive confirmation, and the dark-mode "lighter = nearer" elevation ladder). Single file, no extra icon libraries — only dependency assumed is `react-native-safe-area-context` (near-universal in RN apps; swap for core `SafeAreaView` if you don't have it, but note core's version is iOS-only).

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useMemo, useState } from 'react';
import {
  View,
  Text,
  Image,
  Pressable,
  Switch,
  ScrollView,
  StyleSheet,
  Alert,
  ActivityIndicator,
  useColorScheme,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

// ---------------------------------------------------------------------------
// Tokens — semantic, three-tier (primitive -> semantic). Dark theme uses the
// "lighter surfaces sit nearer" ladder (level 0 app bg -> level 1 card bg),
// not inverted-light or shadow-based elevation.
// ---------------------------------------------------------------------------

const palette = {
  light: {
    bgApp: '#F2F2F7',
    bgSurface: '#FFFFFF',
    borderSubtle: '#E3E3E8',
    textPrimary: '#1C1C1E',
    textMuted: '#6B6B70',
    accentSolid: '#0A84FF',
    dangerText: '#D70015',
    dangerSolid: '#FF3B30',
    onDanger: '#FFFFFF',
    overlayScrim: 'rgba(0,0,0,0.4)',
  },
  dark: {
    bgApp: '#000000',
    bgSurface: '#1C1C1E', // level 1: lighter than app bg, not darker
    borderSubtle: '#38383A',
    textPrimary: '#FFFFFF',
    textMuted: '#9B9BA1',
    accentSolid: '#409CFF',
    dangerText: '#FF6961',
    dangerSolid: '#FF453A',
    onDanger: '#FFFFFF',
    overlayScrim: 'rgba(0,0,0,0.6)',
  },
} as const;

type Tokens = typeof palette.light;

function useTokens(): Tokens {
  const scheme = useColorScheme();
  return scheme === 'dark' ? palette.dark : palette.light;
}

// Smallest target that satisfies both platforms (iOS 44pt floor, Android 48dp floor).
const MIN_TOUCH_TARGET = 48;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface AccountUser {
  name: string;
  email: string;
  avatarUrl?: string;
}

interface NavRow {
  key: string;
  type: 'nav';
  label: string;
  value?: string;
  onPress: () => void;
}

interface ToggleRow {
  key: string;
  type: 'toggle';
  label: string;
  value: boolean;
  onValueChange: (next: boolean) => void;
}

type SettingRowConfig = NavRow | ToggleRow;

interface SettingsSection {
  key: string;
  title?: string;
  footer?: string;
  rows: SettingRowConfig[];
}

export interface AccountSettingsScreenProps {
  user: AccountUser;
  onEditProfile: () => void;
  sections: SettingsSection[];
  /** Must reject (throw) on failure; the screen handles the error alert. */
  onDeleteAccount: () => Promise<void>;
}

// ---------------------------------------------------------------------------
// Profile row
// ---------------------------------------------------------------------------

function Initials({ name }: { name: string }) {
  const initials = name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? '')
    .join('');
  return <Text style={styles.avatarInitials}>{initials}</Text>;
}

function ProfileRow({
  user,
  onPress,
  tokens,
}: {
  user: AccountUser;
  onPress: () => void;
  tokens: Tokens;
}) {
  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`Edit profile, ${user.name}, ${user.email}`}
      hitSlop={8}
      style={({ pressed }) => [
        styles.profileRow,
        { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle },
        pressed && { opacity: 0.6 },
      ]}
    >
      <View style={[styles.avatar, { backgroundColor: tokens.accentSolid }]}>
        {user.avatarUrl ? (
          <Image source={{ uri: user.avatarUrl }} style={styles.avatarImage} />
        ) : (
          <Initials name={user.name} />
        )}
      </View>
      <View style={styles.profileTextBlock}>
        <Text
          style={[styles.profileName, { color: tokens.textPrimary }]}
          numberOfLines={1}
        >
          {user.name}
        </Text>
        <Text
          style={[styles.profileEmail, { color: tokens.textMuted }]}
          numberOfLines={1}
        >
          {user.email}
        </Text>
      </View>
      <Text style={[styles.chevron, { color: tokens.textMuted }]}>{'\u203A'}</Text>
    </Pressable>
  );
}

// ---------------------------------------------------------------------------
// Generic setting row
// ---------------------------------------------------------------------------

function SettingRow({ row, tokens }: { row: SettingRowConfig; tokens: Tokens }) {
  if (row.type === 'toggle') {
    return (
      <View
        style={[styles.row, { minHeight: MIN_TOUCH_TARGET }]}
        accessibilityRole="switch"
        accessibilityState={{ checked: row.value }}
      >
        <Text style={[styles.rowLabel, { color: tokens.textPrimary }]}>{row.label}</Text>
        <Switch
          value={row.value}
          onValueChange={row.onValueChange}
          trackColor={{ false: tokens.borderSubtle, true: tokens.accentSolid }}
          thumbColor={Platform.OS === 'android' ? tokens.bgSurface : undefined}
          accessibilityLabel={row.label}
        />
      </View>
    );
  }

  return (
    <Pressable
      onPress={row.onPress}
      accessibilityRole="button"
      accessibilityLabel={row.label}
      style={({ pressed }) => [
        styles.row,
        { minHeight: MIN_TOUCH_TARGET },
        pressed && { opacity: 0.6 },
      ]}
    >
      <Text style={[styles.rowLabel, { color: tokens.textPrimary }]}>{row.label}</Text>
      <View style={styles.rowTrailing}>
        {row.value ? (
          <Text style={[styles.rowValue, { color: tokens.textMuted }]} numberOfLines={1}>
            {row.value}
          </Text>
        ) : null}
        <Text style={[styles.chevron, { color: tokens.textMuted }]}>{'\u203A'}</Text>
      </View>
    </Pressable>
  );
}

function Section({ section, tokens }: { section: SettingsSection; tokens: Tokens }) {
  return (
    <View style={styles.sectionWrapper}>
      {section.title ? (
        <Text style={[styles.sectionTitle, { color: tokens.textMuted }]}>
          {section.title.toUpperCase()}
        </Text>
      ) : null}
      <View
        style={[
          styles.sectionBody,
          { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle },
        ]}
      >
        {section.rows.map((row, index) => (
          <View key={row.key}>
            <SettingRow row={row} tokens={tokens} />
            {index < section.rows.length - 1 && (
              <View style={[styles.divider, { backgroundColor: tokens.borderSubtle }]} />
            )}
          </View>
        ))}
      </View>
      {section.footer ? (
        <Text style={[styles.sectionFooter, { color: tokens.textMuted }]}>
          {section.footer}
        </Text>
      ) : null}
    </View>
  );
}

// ---------------------------------------------------------------------------
// Delete account — destructive row + confirmation
// ---------------------------------------------------------------------------

function DeleteAccountRow({
  tokens,
  onDeleteAccount,
}: {
  tokens: Tokens;
  onDeleteAccount: () => Promise<void>;
}) {
  const [isDeleting, setIsDeleting] = useState(false);

  const runDelete = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
    } catch (err) {
      Alert.alert(
        'Couldn\u2019t delete account',
        err instanceof Error ? err.message : 'Something went wrong. Please try again.',
      );
    } finally {
      setIsDeleting(false);
    }
  }, [onDeleteAccount]);

  const confirmDelete = useCallback(() => {
    Alert.alert(
      'Delete your account?',
      'This permanently deletes your profile, settings and data. This can\u2019t be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        { text: 'Delete Account', style: 'destructive', onPress: runDelete },
      ],
      { cancelable: true },
    );
  }, [runDelete]);

  return (
    <View style={styles.sectionWrapper}>
      <View
        style={[
          styles.sectionBody,
          { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle },
        ]}
      >
        <Pressable
          onPress={confirmDelete}
          disabled={isDeleting}
          accessibilityRole="button"
          accessibilityLabel="Delete account"
          accessibilityHint="Permanently deletes your account after confirmation"
          style={({ pressed }) => [
            styles.row,
            { minHeight: MIN_TOUCH_TARGET, justifyContent: 'center' },
            pressed && { opacity: 0.6 },
            isDeleting && { opacity: 0.5 },
          ]}
        >
          {isDeleting ? (
            <ActivityIndicator color={tokens.dangerText} />
          ) : (
            <Text style={[styles.rowLabel, styles.deleteLabel, { color: tokens.dangerText }]}>
              Delete Account
            </Text>
          )}
        </Pressable>
      </View>
    </View>
  );
}

// ---------------------------------------------------------------------------
// Screen
// ---------------------------------------------------------------------------

export default function AccountSettingsScreen({
  user,
  onEditProfile,
  sections,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const tokens = useTokens();

  const content = useMemo(
    () => (
      <>
        <ProfileRow user={user} onPress={onEditProfile} tokens={tokens} />
        {sections.map((section) => (
          <Section key={section.key} section={section} tokens={tokens} />
        ))}
        <DeleteAccountRow tokens={tokens} onDeleteAccount={onDeleteAccount} />
      </>
    ),
    [user, onEditProfile, sections, onDeleteAccount, tokens],
  );

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: tokens.bgApp }} edges={['top', 'bottom']}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        contentInsetAdjustmentBehavior="automatic"
      >
        {content}
      </ScrollView>
    </SafeAreaView>
  );
}

// ---------------------------------------------------------------------------
// Example usage (sample data — wire up to real app state)
// ---------------------------------------------------------------------------

export function AccountSettingsScreenExample() {
  const [notificationsOn, setNotificationsOn] = useState(true);
  const [faceIdOn, setFaceIdOn] = useState(false);

  const sections: SettingsSection[] = [
    {
      key: 'preferences',
      title: 'Preferences',
      rows: [
        {
          key: 'notifications',
          type: 'toggle',
          label: 'Notifications',
          value: notificationsOn,
          onValueChange: setNotificationsOn,
        },
        {
          key: 'biometrics',
          type: 'toggle',
          label: Platform.OS === 'ios' ? 'Face ID' : 'Biometric Login',
          value: faceIdOn,
          onValueChange: setFaceIdOn,
        },
        {
          key: 'language',
          type: 'nav',
          label: 'Language',
          value: 'English',
          onPress: () => {},
        },
      ],
    },
    {
      key: 'account',
      title: 'Account',
      rows: [
        { key: 'privacy', type: 'nav', label: 'Privacy', onPress: () => {} },
        { key: 'security', type: 'nav', label: 'Security', onPress: () => {} },
        { key: 'billing', type: 'nav', label: 'Billing', onPress: () => {} },
      ],
    },
    {
      key: 'support',
      title: 'Support',
      rows: [
        { key: 'help', type: 'nav', label: 'Help & Support', onPress: () => {} },
        { key: 'about', type: 'nav', label: 'About', onPress: () => {} },
      ],
    },
  ];

  return (
    <AccountSettingsScreen
      user={{ name: 'Jordan Rivera', email: 'jordan@example.com' }}
      onEditProfile={() => {}}
      sections={sections}
      onDeleteAccount={async () => {
        await new Promise((resolve) => setTimeout(resolve, 1000));
      }}
    />
  );
}

// ---------------------------------------------------------------------------
// Styles
// ---------------------------------------------------------------------------

const styles = StyleSheet.create({
  scrollContent: {
    paddingVertical: 16,
    paddingHorizontal: 16,
    gap: 24,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 14,
    borderWidth: 1,
    paddingVertical: 12,
    paddingHorizontal: 14,
    minHeight: MIN_TOUCH_TARGET,
    gap: 12,
  },
  avatar: {
    width: 52,
    height: 52,
    borderRadius: 26,
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
  },
  avatarImage: {
    width: 52,
    height: 52,
  },
  avatarInitials: {
    color: '#FFFFFF',
    fontSize: 18,
    fontWeight: '600',
  },
  profileTextBlock: {
    flex: 1,
    gap: 2,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
  },
  profileEmail: {
    fontSize: 14,
  },
  chevron: {
    fontSize: 20,
    fontWeight: '400',
  },
  sectionWrapper: {
    gap: 6,
  },
  sectionTitle: {
    fontSize: 12,
    fontWeight: '600',
    letterSpacing: 0.5,
    paddingHorizontal: 4,
  },
  sectionFooter: {
    fontSize: 12,
    paddingHorizontal: 4,
  },
  sectionBody: {
    borderRadius: 14,
    borderWidth: 1,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 12,
    paddingHorizontal: 14,
    gap: 8,
  },
  rowLabel: {
    fontSize: 16,
    flexShrink: 1,
  },
  rowTrailing: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
    flexShrink: 1,
  },
  rowValue: {
    fontSize: 15,
    flexShrink: 1,
  },
  divider: {
    height: StyleSheet.hairlineWidth,
    marginLeft: 14,
  },
  deleteLabel: {
    fontWeight: '600',
  },
});
```

Notes on the choices, since they trace back to the platform rules I pulled:

- **Delete confirmation** uses `Alert.alert` with a `destructive`-styled button and `Cancel` as a separate, non-destructive option — this is the one API that satisfies both platforms at once: iOS renders it as an alert with the destructive role (matching HIG's "use an alert for something the user must know now"), Android renders it as a standard two-action dialog (matching Material's "at most two actions: one confirms, one dismisses").
- **Touch targets** are `minHeight: 48` everywhere interactive, covering iOS's 44pt floor and Android's 48dp floor with one number.
- **Dark mode** follows the "lighter surfaces sit nearer" rule rather than inverting the light palette or using shadows — `bgSurface` is lighter than `bgApp` in the dark set.
- Text uses `numberOfLines` + `flexShrink` instead of fixed heights, so Dynamic Type / Android font scaling doesn't clip the profile name/email or row labels.
- The delete action disables itself and shows a spinner while the deletion promise is in flight, and surfaces failures via a second alert rather than failing silently.

One thing I didn't add: a "type DELETE to confirm" second step. The single destructive-alert confirmation matches both platforms' native pattern for this; say the word if you want the extra friction step instead.
